using System;
using System.Collections.Generic;
using UnityEngine;

namespace BTP.Plants
{
    /// <summary>
    /// (plantId, diseaseId) to the Farm prefab that shows that disease, one per PlantVillage class (24), for the
    /// Farm disease rows. Each entry also names the leaf material that carries the disease, so tests can check that
    /// the prefab really shows it. Regenerated by BTP/Setup/26 - Build Farm Disease Variants; never wired by hand.
    /// </summary>
    [CreateAssetMenu(menuName = "BTP/Disease Variant Catalog", fileName = "DiseaseVariantCatalog")]
    public sealed class DiseaseVariantCatalog : ScriptableObject
    {
        [Serializable]
        public sealed class Entry
        {
            public string plantId;
            public string diseaseId;
            public GameObject farmPrefab;
            [Tooltip("The BTP/Farm Recovery material that carries this disease on the prefab's leaves.")]
            public Material leafMaterial;
        }

        [SerializeField] List<Entry> entries = new List<Entry>();

        public IReadOnlyList<Entry> Entries => entries;

        public bool TryGet(string plantId, string diseaseId, out Entry entry)
        {
            foreach (var candidate in entries)
            {
                if (candidate.plantId == plantId && candidate.diseaseId == diseaseId && candidate.farmPrefab != null)
                {
                    entry = candidate;
                    return true;
                }
            }

            entry = null;
            return false;
        }

        internal void SetEntries(IEnumerable<Entry> values) => entries = new List<Entry>(values);
    }
}
